/* @socom-skeleton stub GetZoommode__11CZFTSWeaponFi */
float CZFTSWeapon::GetZoommode(int index)
{
	/* 0x315950: zoom index-1 for 1 <= index <= count, else 0 */
	if ((u32)m_zoommode.size() < (u32)index || index < 0)
		return 0.0f;

	if (index - 1 < 0)
		return 0.0f;

	return m_zoommode[index - 1];
}

